#!/usr/bin/env python3
"""Generate dorny filters + outside path matcher from ci-path-manifest.yml."""

from __future__ import annotations

import sys
from pathlib import Path

try:
    import yaml
except ImportError:  # pragma: no cover
    yaml = None

REPO_ROOT = Path(__file__).resolve().parents[1]
MANIFEST = REPO_ROOT / ".github" / "ci-path-manifest.yml"
FILTERS_OUT = REPO_ROOT / ".github" / "generated" / "ci-path-filters.yml"
OUTSIDE_OUT = REPO_ROOT / ".github" / "generated" / "ci-path-outside.sh"
BANNER = (
    "# GENERATED by scripts/generate_ci_path_filters.py — do not edit.\n"
    "# Source: .github/ci-path-manifest.yml\n"
)


def _parse_manifest(text: str) -> dict[str, list[str]]:
    if yaml is not None:
        data = yaml.safe_load(text)
        if not isinstance(data, dict):
            raise SystemExit("manifest root must be a mapping")
        out: dict[str, list[str]] = {}
        for key in ("backend", "frontend", "skip"):
            raw = data.get(key) or []
            if not isinstance(raw, list) or not all(isinstance(x, str) for x in raw):
                raise SystemExit(f"manifest.{key} must be a list of strings")
            out[key] = list(raw)
        return out

    sections: dict[str, list[str]] = {"backend": [], "frontend": [], "skip": []}
    current: str | None = None
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if stripped.endswith(":") and not stripped.startswith("-"):
            key = stripped[:-1]
            if key not in sections:
                raise SystemExit(f"unknown manifest section: {key}")
            current = key
            continue
        if current is None or not stripped.startswith("- "):
            raise SystemExit(f"unexpected manifest line: {line}")
        item = stripped[2:].strip()
        if (item.startswith('"') and item.endswith('"')) or (
            item.startswith("'") and item.endswith("'")
        ):
            item = item[1:-1]
        sections[current].append(item)
    return sections


def _glob_to_case_pattern(glob: str) -> str:
    # Bash `case` globs: dir/** → dir/* (prefix match for descendants).
    if glob.endswith("/**"):
        return f"{glob[:-3]}/*"
    return glob


def render_outputs(sections: dict[str, list[str]]) -> tuple[str, str]:
    lines = [BANNER, "backend:\n"]
    for item in sections["backend"]:
        lines.append(f"  - '{item}'\n")
    lines.append("frontend:\n")
    for item in sections["frontend"]:
        lines.append(f"  - '{item}'\n")
    filters = "".join(lines)

    allowed: list[str] = []
    seen: set[str] = set()
    for group in ("backend", "frontend", "skip"):
        for item in sections[group]:
            pat = _glob_to_case_pattern(item)
            if pat not in seen:
                seen.add(pat)
                allowed.append(pat)
    # Emit a sourcable matcher so `|` stays case-syntax, not a string value.
    outside = (
        BANNER
        + "ci_path_is_allowed() {\n"
        + '  case "$1" in\n'
        + f"    {'|'.join(allowed)}) return 0 ;;\n"
        + "    *) return 1 ;;\n"
        + "  esac\n"
        + "}\n"
    )
    return filters, outside


def write_outputs(sections: dict[str, list[str]]) -> None:
    FILTERS_OUT.parent.mkdir(parents=True, exist_ok=True)
    filters, outside = render_outputs(sections)
    FILTERS_OUT.write_text(filters, encoding="utf-8")
    OUTSIDE_OUT.write_text(outside, encoding="utf-8")


def main(argv: list[str]) -> int:
    check = "--check" in argv
    sections = _parse_manifest(MANIFEST.read_text(encoding="utf-8"))
    filters, outside = render_outputs(sections)
    if check:
        before_filters = FILTERS_OUT.read_text(encoding="utf-8") if FILTERS_OUT.is_file() else ""
        before_outside = OUTSIDE_OUT.read_text(encoding="utf-8") if OUTSIDE_OUT.is_file() else ""
        if before_filters != filters or before_outside != outside:
            print(
                "generated CI path filters are stale; run "
                "python scripts/generate_ci_path_filters.py",
                file=sys.stderr,
            )
            return 1
        print("ci path filters up to date")
        return 0
    write_outputs(sections)
    print(f"wrote {FILTERS_OUT.relative_to(REPO_ROOT)}")
    print(f"wrote {OUTSIDE_OUT.relative_to(REPO_ROOT)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
